using namespace hanmo::resident;
namespace {int checks=0;
// 单项失败保原名，统计不掩盖未执行门。
void check(bool value,const char* name){++checks;if(!value)throw std::runtime_error(name);}
// 组件只模拟同候选已登记接受账的存在性；未登记时即使有Common头也不放行。
struct OwnerRead final:ReservationOwnerRead {const CommonStore* common=nullptr;const ChildCareReliefState* state=nullptr;bool reservation_exists(const ReservationRef& r)const override{return r.kind==ReservationRef::Kind::contract&&(r.id=="family_birth:4"||(common&&state&&child_care_relief_reservation_exists(*common,*state,r)));}};
// 总量只用于守恒核验，不作为准入、可支配量或已提供照护的依据。
Integer total_food(const CommonStore& c){Integer result=0;for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.item_id=="food")result+=lot.quantity;return result;}
}
int main(){try{auto catalog=std::make_shared<CommonCatalog>();catalog->places.insert("home",{"home","town",{}});catalog->items.insert("food",{"food",1,1,false,false});CommonState seed;seed.identity.world_id[0]=8;seed.identity.execution_epoch=3;seed.identity.revision=2;seed.metadata.ruleset_id=dynamic_ruleset_id;seed.metadata.player_actor_id="parent";seed.next_instance_id=20;ActorRecord actor;actor.id="parent";actor.alive=true;actor.available=true;actor.location=SettlementLocation{"town","home"};actor.inventory_id="bag";seed.actors.insert(actor.id,actor);const Owner own{Owner::Kind::actor,"parent",{}},foreign{Owner::Kind::actor,"other",{}};InventoryView bag{"bag",own,200,0,{{"lot:2","food",{},8,own,{},{ }},{"lot:3","food",{},50,foreign,{},{}}},{}};seed.inventories.insert("bag",bag);seed.inventories.insert("elsewhere",{"elsewhere",own,100,0,{},{}});seed.wallets.insert("money",{"money",own,10,{},{}});CommonStore c(seed,catalog);OwnerRead owners;c.bind_reservation_owners(&owners);ChildCareReliefState state;ChildCareReliefSource terms;terms.provider_actor_id="parent";terms.terms={"home","bag","food",2,2,3,{}};owners.common=&c;owners.state=&state;check(c.append_fact({"family_birth:4","family_birth_accepted","family_birth"}).ok,"upstream old birth header fixture");c.state().inventories.find("bag")->lots.push_back({"lot:5","food",{ReservationRef::Kind::contract,"family_birth:4"},3,own,{},{}});auto before=encode_common_state(c.state());auto quote=preview_child_care_relief_supply(c,terms);check(quote.ok&&quote.value.quantity==6&&quote.value.available_before==8,"own unreserved finite supply");check(compare_boundary(before,encode_common_state(c.state())).exact(),"preview touched supply or IDs");auto too_much=terms;too_much.terms.prepaid_periods=5;check(!preview_child_care_relief_supply(c,too_much).ok,"foreign cargo used for childcare");check(!reserve_child_care_relief_recipe(c,state,quote.value,"family_care_relief:1").ok,"unallocated contract held food");check(c.append_fact({"family_care_relief:1","family_care_relief_accepted","family_care_relief"}).ok,"append accepted source head");check(!reserve_child_care_relief_recipe(c,state,quote.value,"family_care_relief:1").ok,"header without typed owner accepted");ChildCareReliefAgreement accepted;accepted.source=terms;accepted.reserved_food=quote.value.quantity;state.agreements.insert("family_care_relief:1",accepted);auto recipe=reserve_child_care_relief_recipe(c,state,quote.value,"family_care_relief:1");check(recipe.ok,"actual accepted responsibility reserve quote");auto atomic=recipe.value;atomic.operations.push_back(WalletDelta{"missing",1,true});auto original=encode_common_state(c.state());check(!c.apply_resources(atomic).ok&&compare_boundary(original,encode_common_state(c.state())).exact(),"late recipe failure left held grain or allocated lot");auto sum=total_food(c);check(c.apply_resources(recipe.value).ok&&validate_child_care_relief_reservation(c,state,"family_care_relief:1",6).ok,"exact contract six units held");check(c.count("bag","food",{own},{ReservationRef::Kind::contract,"family_birth:4"}).value==3,"new reservation stole original birth food");check(total_food(c)==sum&&c.count("bag","food",{own}).value==2,"reservation consumed or duplicated food");check(!reserve_child_care_relief_recipe(c,state,quote.value,"family_care_relief:1").ok,"stale replay doubled reservation");auto consume=consume_child_care_relief_recipe(c,state,"family_care_relief:1",6,2);check(consume.ok&&c.apply_resources(consume.value).ok,"one actual finite care ration recipe");check(total_food(c)==sum-2&&validate_child_care_relief_reservation(c,state,"family_care_relief:1",4).ok,"actual food consumption did not reduce exact held source");check(!consume_child_care_relief_recipe(c,state,"family_care_relief:1",4,1).ok,"partial undocumented care consumption accepted");c.state().wallets.find("money")->reserved.push_back({{ReservationRef::Kind::contract,"family_care_relief:1"},1});check(!release_child_care_relief_recipe(c,state,"family_care_relief:1",4).ok,"unexpected cash released with food contract");c.state().wallets.find("money")->reserved.clear();auto release=release_child_care_relief_recipe(c,state,"family_care_relief:1",4);check(release.ok&&c.apply_resources(release.value).ok&&total_food(c)==sum-2,"release refunded consumed food or transferred property");check(c.count("bag","food",{own},{ReservationRef::Kind::contract,"family_birth:4"}).value==3,"new cancellation released original birth obligation");check(validate_child_care_relief_reservation(c,state,"family_care_relief:1",0).ok&&c.count("bag","food",{own}).value==6,"remaining original food not released");check(!release_child_care_relief_recipe(c,state,"family_care_relief:1",4).ok,"second stale release admitted");auto public_terms=terms;c.state().inventories.find("bag")->owner={Owner::Kind::organization,"public",{}};check(!preview_child_care_relief_supply(c,public_terms).ok,"public inventory treated as personal");std::cout<<"CHILD_CARE_RELIEF_RESOURCES "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<"CHILD_CARE_RELIEF_RESOURCES "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
